<template>
  <div class="select-time">
    <div class="time-box" @click="openTimeMask">
      <span>取件时间</span>
      <div>
        <span>{{showTime}}</span>
        <i class="icon iconfont color-a">&#xe62b;</i>
      </div>
    </div>
    <div class="mask time-mask" :class="{'active': showTimeMask}" @click="openTimeMask">
      <div class="mask-content " @click.stop="preventDefault">
        <div class="title-box">
          <span @click="openTimeMask">取消</span>
          <span class="title">时间</span>
          <span @click="openTimeMask('confirm')">确定</span>
        </div>
        <mt-picker :slots="timeList" :itemHeight="40" @change="onValuesChange"></mt-picker>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'SelectTime',
  data () {
    return {
      showTimeMask: false, // 帮我买 是否显示时间弹窗
      timeList: [
        {
          flex: 1,
          values: [],
          className: 'slot1',
          textAlign: 'center'
        }, {
          flex: 1,
          values: [],
          className: 'slot3',
          textAlign: 'center'
        }
      ],
      showTime: '', // 显示 时间
      dayIndex: 0, // 帮我送 时间选择的是第几天
      dayValue: '今天',
      pickerValue: [], // 时间picker选择的值
      timeOther: []
    }
  },
  props: ['timeInfo', 'type'],
  created () {
    if (this.timeInfo.length > 0) {
      console.log('6666666', this.timeInfo)
      let timeOther = []
      this.timeInfo.map(item => {
        this.timeList[0].values.push(item.show)
        let arr = item.timeList.map(item => item.time)
        timeOther.push(arr)
      })
      this.timeList[1].values = timeOther[0]
      this.dayValue = this.timeList[0].values[0]
      let nowTime = this.$globalData.time
      if (nowTime) {
        this.$emit('getTime', nowTime)
        let nowTimeArr = nowTime.split(' ')
        for (let i = 0; i < this.timeInfo.length; i++) {
          if (this.timeInfo[i].day == nowTimeArr[0]) {
            nowTimeArr[0] = this.timeInfo[i].show
          }
        }
        this.showTime = nowTimeArr[0] + ' ' + nowTimeArr[1]
      } else {
        this.$emit('getTime', this.timeInfo[0].day + ' ' + timeOther[0][0])
        let firstTxt = this.type == 'send' ? '立即取件' : '立即配送'
        this.showTime = timeOther[0][0] = firstTxt + ' ' + timeOther[0][0]
      }
      this.timeOther = timeOther
    } else {
      this.showTime = this.type == 'send' ? '立即取件' : '立即配送'
    }
  },
  methods: {
    // 帮我送 打开时间弹窗
    openTimeMask (type) {
      if (this.timeInfo.length == 0) {
        return
      }
      this.showTimeMask = !this.showTimeMask
      if (type == 'confirm') {
        var values = this.pickerValue
        this.showTime = values[1].indexOf('立即') != -1 ? values[1] : values[0] + ' ' + values[1]
        let time = values[1].indexOf('立即') != -1 ? values[1].splice(0, 5) : values[1]
        let day = this.timeInfo[this.dayIndex].day
        this.$emit('getTime', day + ' ' + time)
      }
    },
    // 选择时间
    onValuesChange (picker, values) {
      let dayList = this.timeList[0].values
      // 切换天的时候，对应的time也要切换
      if (dayList.length > 0 && values[0] != this.dayValue) {
        this.dayValue = values[0]
        for (var i = 0; i < dayList.length; i++) {
          if (dayList[i] == values[0]) {
            console.log('44444')
            this.dayIndex = i
            this.timeList[1].values = this.timeOther[i]
            break
          }
        }
      }
      this.pickerValue = values
    },
    preventDefault () {
      return false
    }
  }
}
</script>

<style lang="stylus" scoped>
.select-time
  .time-box
    background #fff
    flexbox()
    align-items center
    justify-content space-between
    padding 18px 10px
    font-size 14px
  .time-mask
    .picker
      .picker-slot
        font-size 14px
      .picker-item
        opacity .4
        &.picker-selected
         opacity 1
  .title-box
    flexbox()
    justify-content space-between
    align-items center
    font-size 14px
    padding 15px 10px
    border-bottom 1PX solid #e5e5e5
    .title
      font-size 15px
</style>
