<template>
    <div class="order-tip">
      <div class="tip-box" @click="openMask">
        <span>小费</span>
        <div>
          <span v-if="tip > 0">¥{{tip}}</span>
          <span class="color-a" v-else>加小费抢单更快哦</span>
          <i class="icon iconfont color-a">&#xe62b;</i>
        </div>
      </div>
      <div class="mask tip-mask" :class="{active: showMask}" @click="openMask">
        <div class="mask-content " @click.stop="preventClose">
          <div class="title-box">
            <span @click="openMask">取消</span>
            <span class="title">小费</span>
            <span @click="confirm">确定</span>
          </div>
          <div class="fee-box">
            <div class="select-box">
              <div class="item" :class="{'active': selectIndex == index}" @click="selectTip(index)" v-for="(item, index) in list" :key="index">
                <span v-show="item == 0">不加了</span>
                <span v-show="item != 0">¥{{item}}</span>
              </div>
            </div>
            <div class="input-box" :class="{'active': selectIndex == -1}" @click="selectTip(-1)">
              <span>其他金额</span>
              <span v-show="selectIndex == -1">：¥</span>
              <span ref="widthTag" class="width-tag">{{inputFee}}</span>
              <input class="fee-input" :style="inputStyle" autocomplete="off" type="text" maxlength="8" value="inputFee" ref="feeInput" v-model="inputFee" v-show="selectIndex == -1" @input="feeInput">
            </div>
          </div>
        </div>
      </div>
    </div>
</template>

<script>
export default {
  name: 'OrderTip',
  data () {
    return {
      showMask: false,
      list: [ 0, 2, 5, 8, 10, 20 ],
      selectIndex: -1, // -1表示其他金额
      fee: 0,
      inputFee: '',
      inputStyle: ''
    }
  },
  props: [ 'tip' ],
  created () {
    for (var i = 0; i < this.list.length; i++) {
      if (this.list[i] == this.tip) {
        this.selectIndex = i
        this.fee = this.tip
        break
      }
    }
    if (this.selectIndex == -1) {
      this.inputFee = this.tip
    }
  },
  methods: {
    openMask (type) {
      this.showMask = !this.showMask
      if (this.showMask) {
        for (var i = 0; i < this.list.length; i++) {
          if (this.list[i] == this.tip) {
            this.selectIndex = i
            this.fee = this.tip
            break
          }
        }
        if (this.selectIndex == -1) {
          this.inputFee = this.tip
        }
      }
    },
    confirm () {
      let fee = this.selectIndex == -1 ? this.inputFee * 1 : this.fee
      if (!fee) {
        fee = 0
      }
      this.$emit('getTip', fee)
      this.showMask = false
    },
    // 禁止点击穿透
    preventClose (type) {
      return false
    },
    selectTip (type) {
      if (this.selectIndex != type) {
        this.selectIndex = type
      }
      if (type == -1) {
        this.$nextTick(function () {
          this.$refs.feeInput.focus()
        })
      } else {
        this.fee = this.list[type]
      }
    },
    feeInput () {
      this.$nextTick(function () {
        this.inputStyle = this.inputFee ? `width:${this.$refs.widthTag.clientWidth}px` : `width:2px`
      })
    }

  }
}
</script>

<style lang="stylus" scoped>
.order-tip
  .tip-box
    background #fff
    flexbox()
    align-items center
    justify-content space-between
    font-size 14px
    padding 18px 10px
    .icon
      vertical-align middle
  .tip-mask
    .mask-content
      color #000
      .title-box
        flexbox()
        justify-content space-between
        align-items center
        font-size 14px
        padding 15px 10px
        border-bottom 1PX solid #e5e5e5
        .title
          font-size 15px

      .fee-box
        .select-box
          flexbox()
          flex-wrap wrap
          padding 15px 0 0 13px
          font-size 14px
          .item
            margin-right 13px
            margin-bottom 13px
            width -webkit-calc(33.3333% - 13px)
            width calc(33.3333% - 13px)
            padding 10px
            box-sizing border-box
            border 1PX solid #e5e5e5
            text-align center
            &.active
              color $color-main
              border-color $color-main
              background rgba($color-main, .1)
        .input-box
          flexbox()
          justify-content center
          align-items center
          font-size 14px
          border 1PX solid #e5e5e5
          padding 8px
          margin 0 13px 15px
          position relative
          &.active
            color $color-main
            border-color $color-main
          .fee-input
            width 2PX
            text-align center
            color $color-main
            transition all .3s
            display inline-block
          .width-tag
            position absolute
            top -9999px
            left -9999px

</style>
