<template>
    <div class="order-map">
      <baidu-map class="bm-view" ak="4c1bb2055e24296bbaef36574877b4e2" :center="nowMap.center" :zoom="nowMap.zoom" @ready="mapHandler">
        <!-- start点 -->
        <bm-marker :position="start.point" :icon="{url: require('../../static/img/send.png'), size: {width:30, height: 30}, opts:{imageSize: {width:30, height: 30}}}" v-if=" start && type == 'send' "></bm-marker>
        <bm-marker :position="start.point" :icon="{url: require('../../static/img/buy.png'), size: {width:30, height: 30}, opts:{imageSize: {width:30, height: 30}}}" v-if=" start && type == 'buy' "></bm-marker>
        <!-- end点 -->
        <!--<bm-marker :position="end.point" :icon="{url: require('../../static/img/end.png'), size: {width:30, height: 30}, opts:{imageSize: {width:30, height: 30}}}" v-if="end"></bm-marker>-->
        <!-- 显示距离 -->
        <bm-overlay pane="labelPane" class="distance" @draw="draw" >
          <img class="img" :src="require('../../static/img/end.png')" alt="" >
          <div class="number" :style="numberStyle" id="number" ref="number" v-show="showDistance && start && end ">{{distance}}公里<i class="icon iconfont">&#xe791;</i></div>
        </bm-overlay>
      </baidu-map>
    </div>
</template>

<script>
import BaiduMap from 'vue-baidu-map/components/map/Map'
import BmMarker from 'vue-baidu-map/components/overlays/Marker'
import BmOverlay from 'vue-baidu-map/components/overlays/Overlay'
export default {
  name: 'OrderMap',
  data () {
    return {
      nowMap: { center: '', zoom: 15 },
      distance: -1,
      showDistance: false,
      numberStyle: ''
    }
  },
  props: ['start', 'end', 'type'],
  methods: {
    mapHandler ({ BMap, map }) {
      this.showDistance = true
      if (this.start && this.end) {
        this.getDistance()
        var viewportOptions = {
          zoomFactor: -1
        }
        this.nowMap = map.getViewport([this.start.point, this.end.point], viewportOptions)
        return
      }
      this.nowMap.center = this.start ? this.start.point : this.end.point
      this.nowMap.zoom = 15
    },
    draw ({ el, BMap, map }) {
      const pixel = map.pointToOverlayPixel(new BMap.Point(this.end.lng, this.end.lat))
      el.style.left = pixel.x - 15 + 'px'
      el.style.top = pixel.y - 15 + 'px'
    },
    async getDistance () {
      try {
        let distanceParam = {
          end_lat: this.end.point.lat,
          end_lng: this.end.point.lng,
          start_lat: this.start.point.lat,
          start_lng: this.start.point.lng
        }
        let res = await this.$api.getDistance(distanceParam)
        if (res.errorMsg) {
          return
        }
        this.distance = res.distance.toFixed(2)
        this.$nextTick(() => {
          let width = this.$refs.number.clientWidth
          let left = (width / 2 - 15).toFixed(2)
          this.numberStyle = `left:${-left}PX`
        })
      } catch (e) {
        console.log('获取距离失败 getDistance', e)
      }
    }
  },
  components: {
    BaiduMap, BmMarker, BmOverlay
  }
}
</script>

<style lang="stylus" scoped>
.order-map
  .bm-view
    height 175px
    .distance
      position absolute
      top 0
      left 0
      .number
        white-space nowrap
        padding 8PX 10PX
        font-size 12PX
        background #000000
        color #ffffff
        border-radius 8PX
        position absolute
        top -38PX
        left -18PX
        .icon
          position absolute
          left 0
          right 0
          bottom -10PX
          color #000000
          text-align center
      .img
        width 30PX
</style>
